INSERT INTO t_session_entries (
    session_id, id, entry_seq, parent_id, type, timestamp, payload
) VALUES (
    #{sessionId}, #{id}, #{entrySeq}, #{parentId}, #{type}, #{timestamp}, CAST(#{payload} AS JSONB)
)

INSERT INTO t_session_records (
    session_id, id, record_seq, lane, run_id, type, timestamp, payload
) VALUES (
    #{sessionId}, #{id}, #{recordSeq}, #{lane}, #{runId}, #{type}, #{timestamp}, CAST(#{payload} AS JSONB)
)

INSERT INTO t_session_events (
    session_id, event_id, event_seq, anchor_entry_id, type, created_at, payload
) VALUES (
    #{sessionId}, #{eventId}, #{eventSeq}, #{anchorEntryId},
    #{type}, #{createdAt}, CAST(#{payload} AS JSONB)
)

INSERT INTO t_session_event_projection (
    session_id, anchor_entry_id, event_count, mapping_source
) VALUES (
    #{sessionId}, #{anchorEntryId}, #{eventCount}, #{mappingSource}
)

