UPDATE t_sessions
SET state = 'idle',
    resource_version = resource_version + 1,
    updated_at = #{updatedAt}
WHERE id = #{sessionId}
  AND state = 'running'

UPDATE t_sessions
SET thinking = #{thinking},
    resource_version = resource_version + 1,
    updated_at = #{updatedAt}
WHERE id = #{sessionId}
  AND state = 'idle'

UPDATE t_sessions
SET display_name = #{displayName},
    resource_version = resource_version + 1,
    updated_at = #{updatedAt}
WHERE id = #{sessionId}

